def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    values = sorted(set(a))
    ranks = {value: i + 1 for i, value in enumerate(values)}
    tree = [0] * (len(values) + 1)
    result = []

    for i, height in enumerate(a):
        rank = ranks[height]

        count_not_taller = 0
        pos = rank
        while pos:
            count_not_taller += tree[pos]
            pos -= pos & -pos

        result.append(min(i, k) - count_not_taller)

        pos = rank
        while pos < len(tree):
            tree[pos] += 1
            pos += pos & -pos

        if i >= k:
            pos = ranks[a[i - k]]
            while pos < len(tree):
                tree[pos] -= 1
                pos += pos & -pos

    return result
